package com.t1doo.aiyou.data

import com.t1doo.aiyou.domain.*
import com.t1doo.aiyou.model.*
import java.io.ByteArrayOutputStream
import java.util.UUID
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test

class SavedQuestionFullBackupTest {
    @Test fun oldEmptyDocumentBytesAreUnchangedAndQuestionTableCannotEnterOldHeader() {
        val d=FullBackupData("00000000-0000-0000-0000-000000000001",100,List(14) { emptyList() },emptyList(),emptyList(),null)
        val bytes=FullBackupCodec.encode(d)
        try {
            // Generated by the actual 720a encoder before this change, with the same fixed logical input.
            assertEquals(1225,bytes.size)
            assertEquals("b4add1daf9f1a80e71cd4f128f22728eb1b11ce2ebc79578d89918acfc5e6f30",packageHex(packageHash(bytes)))
            val decoded=FullBackupCodec.decode(bytes)
            try { assertEquals(8,decoded.version);assertEquals(16,decoded.tables.size);assertTrue(decoded.tables.drop(13).all {it.isEmpty()}) }
            finally { decoded.release() }
        } finally { bytes.fill(0);d.release() }
    }
    @Test fun independentQuestionsCrossKeyPendingDoneReplayAndReexportNeverReviveDeleted():Unit=runBlocking {
        FullFixture().use { source -> FullFixture(90).use { target -> FullFixture(120).use { third ->
            val stores=listOf(source,target,third).map { SqlSavedQuestionRepository(it.gateway,it.key) }
            try {
                val kept=uuid(); val deleted=uuid()
                stores[0].save(write(kept,0,"离线保存的问题🙂"));stores[0].save(write(deleted,0,"之后明确删除的问题"))
                stores[0].save(write(deleted,1,null,at=20))
                val snap=source.backup.capture(uuid(),100)
                assertEquals(0,snap.summary.records);assertEquals(2,snap.summary.savedQuestions)
                val bytes=export(source,snap);snap.release()
                assertEquals("AIYOUF15",bytes.copyOfRange(0,8).toString(Charsets.US_ASCII))
                val pack=target.backup.open({bytes.inputStream()},password())
                try {
                    target.checkpoint={ if(it=="full-intent") error("Synthetic pending intent interruption") }
                    assertThrows(Exception::class.java) { runBlocking { target.backup.restore(pack) { true } } }
                    assertFalse(target.backup.completed(pack));assertTrue(stores[1].list().isEmpty())
                    target.checkpoint={ if(it=="full-committed") error("Synthetic durable DONE acknowledgement loss") }
                    assertThrows(Exception::class.java) { runBlocking { target.backup.restore(pack) { true } } }
                    target.checkpoint={};assertTrue(target.backup.completed(pack));assertTrue(target.backup.restore(pack) { true }.replayed)
                    assertEquals("离线保存的问题🙂",stores[1].read(kept)!!.question);assertNull(stores[1].read(deleted)!!.question)
                    val a=source.db.read("SELECT payload FROM saved_questions WHERE id=?",kept).single().single() as ByteArray
                    val b=target.db.read("SELECT payload FROM saved_questions WHERE id=?",kept).single().single() as ByteArray
                    assertFalse(a.contentEquals(b));assertTrue(target.db.read("SELECT * FROM entries").isEmpty())
                    stores[1].save(write(kept,1,null,at=30));assertTrue(target.backup.restore(pack) { true }.replayed)
                    assertNull(stores[1].read(kept)!!.question)
                    val again=target.backup.capture(uuid(),200)
                    assertEquals(15,(again as FullBackupData).version) // All tombstones still force v15.
                    val next=export(target,again);again.release()
                    val imported=third.backup.open({next.inputStream()},password())
                    try { third.backup.restore(imported) { true };assertTrue(stores[2].list().isEmpty());assertNull(stores[2].read(kept)!!.question) }
                    finally { imported.release();next.fill(0) }
                } finally { pack.release();bytes.fill(0) }
            } finally { stores.forEach { it.wipeKey() } }
        } } }
    }
    @Test fun malformedPortableQuestionFailsBeforeIntentAndExistingQuestionIsNotAnEmptyTarget():Unit=runBlocking {
        FullFixture().use { source -> FullFixture(90).use { target ->
            val a=SqlSavedQuestionRepository(source.gateway,source.key);val b=SqlSavedQuestionRepository(target.gateway,target.key)
            try {
                val id=uuid();a.save(write(id,0,"需明确保留的问题"))
                val snap=source.backup.capture(uuid(),100) as FullBackupData
                // Authenticated outer document with inconsistent inner private metadata is still invalid.
                val row=snap.tables[13].single().toMutableList();row[0]=uuid()
                val changed=FullBackupData(snap.id,snap.created,snap.tables.take(13)+listOf(listOf(row)),emptyList(),emptyList(),null)
                val bad=RecordMediaPackageCipher().sealFull(changed,password(),{error("No media")},{true})
                val out=ByteArrayOutputStream();try { bad.writeTo(out) { true } } finally { bad.release() }
                val forged=out.toByteArray()
                try { assertThrows(Exception::class.java) { runBlocking { target.backup.open({forged.inputStream()},password()) } }
                    assertTrue(target.db.read("SELECT * FROM record_package_receipts").isEmpty());assertTrue(b.list().isEmpty())
                } finally { forged.fill(0) }
                val bytes=export(source,snap)
                val existing=b.save(write(uuid(),0,"目标已有问题"));val pack=target.backup.open({bytes.inputStream()},password())
                try { assertThrows(Exception::class.java) { runBlocking { target.backup.restore(pack) { true } } }
                    assertEquals(existing.question,b.read(existing.id)!!.question);assertFalse(target.backup.completed(pack))
                } finally { pack.release();bytes.fill(0);changed.release();snap.release() }
            } finally { a.wipeKey();b.wipeKey() }
        } }
    }
    private suspend fun export(f:FullFixture,snapshot:FullBackupSnapshot):ByteArray {
        val p=f.backup.seal(snapshot,password());val out=ByteArrayOutputStream()
        return try { p.writeTo(out) { true };out.toByteArray() } finally { p.release() }
    }
    companion object {
        private fun uuid()=UUID.randomUUID().toString()
        private fun password()="synthetic-question-backup-123".toCharArray()
        private fun write(id:String,version:Long,q:String?,at:Long=10)=SaveQuestion(id,version,uuid(),q,at)
    }
}
